step.script:
var payload = JSON.parse(msg);

// Sanitize patient ID (numbers only)
var patientId = payload.patientId.replace(/[^0-9]/g, '');

// Sanitize file name (remove special chars)
var fileName = payload.fileName.replace(/[^a-zA-Z0-9._-]/g, '_');

var result = {
  patientId: patientId,
  fileName: fileName,
  mimeType: payload.mimeType,
  base64Data: payload.base64,
  receivedAt: payload.originalTimestamp,
  dataLength: payload.base64.length
};

return JSON.stringify(result);

var payload = JSON.parse(msg);

// Create ACK response
var ack = {
  status: 'OK',
  message: 'File received and processed',
  fileName: payload.fileName,
  patientId: payload.patientId,
  processedAt: new Date().toISOString(),
  recordId: java.util.UUID.randomUUID().toString()
};

logger.info('Sending ACK for ' + payload.fileName);

return JSON.stringify(ack);

// This response goes back to the Node.js service
// The service is waiting for HTTP 200 with ACK in body

var payload = JSON.parse(msg);

var response = {
  status: 200,
  message: 'File processed successfully',
  fileName: payload.fileName,
  patientId: payload.patientId,
  timestamp: new Date().toISOString()
};

// Set HTTP response code
responseStatus = 200;

// Set response headers (optional)
responseHeaders = {
  'Content-Type': 'application/json',
  'X-Mirth-Status': 'OK'
};

// Response body
return JSON.stringify(response);

// If something goes wrong, still send back a response
// so Node.js service doesn't hang on timeout

if (error) {
  logger.error('Error processing file: ' + error);
  responseStatus = 500;
  return JSON.stringify({
    status: 500,
    error: error.toString()
  });
}

return response;
